# Autogenerated wrapper script for intel_opencl_rt_jll for x86_64-w64-mingw32
export libintelocl

using OpenCL_jll
using MSVCRuntime_jll
JLLWrappers.@generate_wrapper_header("intel_opencl_rt")
JLLWrappers.@declare_library_product(libintelocl, "intelocl64.dll")
function __init__()
    JLLWrappers.@generate_init_header(OpenCL_jll, MSVCRuntime_jll)
    JLLWrappers.@init_library_product(
        libintelocl,
        "bin\\intelocl64.dll",
        nothing,
    )

    JLLWrappers.@generate_init_footer()
        # Register this driver with OpenCL_jll
    if OpenCL_jll.is_available()
        push!(OpenCL_jll.drivers, libintelocl)
    end

end  # __init__()
